enum class NotificationType { Email, SMS };

class Notification {
public:
    virtual ~Notification() = default;
    virtual void send() const = 0;
};

class EmailNotification : public Notification {
public:
    void send() const override {
        std::cout << "Sending Email\n";
    }
};

class SmsNotification : public Notification {
public:
    void send() const override {
        std::cout << "Sending SMS\n";
    }
};

class NotificationFactory {
public:
    static std::unique_ptr<Notification> create(NotificationType type) {
        switch (type) {
            case NotificationType::Email:
                return std::make_unique<EmailNotification>();
            case NotificationType::SMS:
                return std::make_unique<SmsNotification>();
        }
        throw std::invalid_argument("Unknown notification type");
    }
};

int main() {
    auto email = NotificationFactory::create(NotificationType::Email);
    auto sms = NotificationFactory::create(NotificationType::SMS);

    email->send();
    sms->send();
}

std::unique_ptr<Notification> createNotification(NotificationType type) {
    switch (type) {
        case NotificationType::Email:
            return std::make_unique<EmailNotification>();
        case NotificationType::SMS:
            return std::make_unique<SmsNotification>();
    }
    throw std::invalid_argument("Unknown notification type");
}

